<?php require __DIR__.'/bootstrap.php';require_admin();$orders=read_json('orders.json',[]);$products=read_json('products.json',[]);$notifications=read_json('notifications.json',[]);$subs=read_json('subscribers.json',[]);$requests=read_json('custom-requests.json',[]);$paid=array_filter($orders,fn($o)=>($o['payment_status']??'')==='paid');$revenue=array_sum(array_map(fn($o)=>(float)$o['total'],$paid));site_header('Admin dashboard'); ?>
